import React, { Component } from 'react';
import axios from 'axios';
import '../css/CustomerHomeComponent.css';
import ProductDetailComponent from './ProductDetailComponent';
import ServiceModalComponent from './ServiceModalComponent';
import CartModalComponent from './CartModalComponent';

class CustomerHomeComponent extends Component {
  constructor(props) {
    super(props);
    this.state = {
      categories: [],
      products: [],
      selectedCategory: 'all',
      searchTerm: '',
      tableName: 'Bàn 01',
      accountName: 'Khách hàng',
      cart: [],
      customerOrders: [],
      loadingCustomerOrders: false,
      availableVouchers: [],
      selectedVoucher: null,
      voucherInput: '',
      voucherError: '',
      isSubmittingOrder: false,
      isSubmittingServiceRequest: false,
      notification: null,
      selectedProductForDetail: null,
      showServiceModal: false,
      showCartModal: false
    };
  }

  componentDidMount() {
    this.fetchMenuData();
    this.fetchCustomerOrders();
    this.fetchAvailableVouchers();
    this.menuRefreshTimer = setInterval(this.fetchProducts, 5000);
    this.orderRefreshTimer = setInterval(this.fetchCustomerOrders, 5000);
    const storedUsername = localStorage.getItem('username');
    if (storedUsername) {
      this.setState({ accountName: storedUsername });
    }
  }

  componentWillUnmount() {
    clearInterval(this.menuRefreshTimer);
    clearInterval(this.orderRefreshTimer);
    clearTimeout(this.notificationTimer);
  }

  fetchMenuData = () => {
    const token = localStorage.getItem('token');
    const headers = token ? { 'x-access-token': token, 'Authorization': token } : {};

    // Gọi API kèm header authorization nếu cần
    axios.get('/api/admin/categories', { headers })
      .then(res => {
        if (Array.isArray(res.data)) {
          this.setState({ categories: res.data });
        }
      })
      .catch(err => console.error("Lỗi tải danh mục:", err));

    this.fetchProducts();
  }

  fetchProducts = () => {
    const token = localStorage.getItem('token');
    const headers = token ? { 'x-access-token': token, 'Authorization': token } : {};
    axios.get('/api/admin/products', { headers })
      .then(res => {
        if (Array.isArray(res.data)) {
          this.setState((state) => ({
            products: res.data,
            selectedProductForDetail: state.selectedProductForDetail
              ? res.data.find(product => product._id === state.selectedProductForDetail._id) || state.selectedProductForDetail
              : null
          }));
        }
      })
      .catch(err => console.error("Lỗi tải thực đơn:", err));
  }

  fetchCustomerOrders = () => {
    const token = localStorage.getItem('token');
    if (!token) return;
    axios.get('/api/admin/my/orders', { headers: { 'x-access-token': token } })
      .then(res => this.setState({ customerOrders: Array.isArray(res.data) ? res.data : [], loadingCustomerOrders: false }))
      .catch(err => {
        this.setState({ loadingCustomerOrders: false });
        console.error('Không thể tải đơn hàng của khách:', err);
      });
  }

  fetchAvailableVouchers = () => {
    const token = localStorage.getItem('token');
    if (!token) return;
    axios.get('/api/admin/available-vouchers', { headers: { 'x-access-token': token } })
      .then(res => this.setState({ availableVouchers: Array.isArray(res.data) ? res.data : [] }))
      .catch(err => console.error('Không thể tải mã giảm giá:', err));
  }

  showNotification = (type, title, message) => {
    clearTimeout(this.notificationTimer);
    this.setState({ notification: { type, title, message } });
    this.notificationTimer = setTimeout(() => this.setState({ notification: null }), 4800);
  }

  getCartSubtotal = () => this.state.cart.reduce(
    (sum, item) => sum + Number(item.totalPrice || item.price * item.quantity || 0), 0
  )

  getVoucherDiscount = (voucher = this.state.selectedVoucher) => {
    if (!voucher) return 0;
    const subtotal = this.getCartSubtotal();
    if (subtotal < Number(voucher.minOrder || 0)) return 0;
    const discount = voucher.discountType === 'percent'
      ? Math.floor(subtotal * Number(voucher.discount || 0) / 100)
      : Number(voucher.discount || 0);
    return Math.min(Math.max(discount, 0), subtotal);
  }

  selectVoucher = (voucher) => {
    if (this.getCartSubtotal() < Number(voucher.minOrder || 0)) {
      this.setState({ voucherError: `Đơn hàng tối thiểu ${Number(voucher.minOrder || 0).toLocaleString('vi-VN')}đ để dùng mã này.` });
      return;
    }
    this.setState({ selectedVoucher: voucher, voucherInput: voucher.code, voucherError: '' });
  }

  applyVoucherCode = () => {
    const code = this.state.voucherInput.trim().toUpperCase();
    const voucher = this.state.availableVouchers.find(item => String(item.code).toUpperCase() === code);
    if (!voucher) {
      this.setState({ selectedVoucher: null, voucherError: 'Không tìm thấy mã giảm giá còn hiệu lực.' });
      return;
    }
    this.selectVoucher(voucher);
  }

  handleAddToCart = (itemWithDetails) => {
    const currentProduct = this.state.products.find(product => product._id === itemWithDetails._id);
    if (itemWithDetails.status !== 'Active' || (currentProduct && currentProduct.status !== 'Active')) {
      this.showNotification('error', 'Món đã hết', 'Món này vừa được cập nhật hết hàng. Vui lòng chọn món khác.');
      this.setState({ selectedProductForDetail: null });
      return;
    }
    this.setState(state => ({
      cart: [...state.cart, itemWithDetails],
      selectedProductForDetail: null
    }));
  }

  handleSubmitOrder = async () => {
    const { cart, tableName, selectedVoucher } = this.state;
    if (cart.length === 0) {
      this.showNotification('error', 'Chưa có món để gọi', 'Thêm món vào giỏ trước khi gửi bếp nhé.');
      return;
    }
    if (this.state.isSubmittingOrder) return;
    this.setState({ isSubmittingOrder: true });
    try {
      const token = localStorage.getItem('token');
      const response = await axios.post('/api/admin/orders', {
        tableNo: tableName,
        voucherCode: selectedVoucher?.code || '',
        items: cart.map(item => ({
          product: item._id,
          quantity: item.quantity,
          note: item.note,
          selectedToppings: item.selectedToppings
        }))
      }, {
        headers: token ? { 'x-access-token': token } : {}
      });
      this.setState(state => ({
        customerOrders: [response.data, ...state.customerOrders.filter(order => order._id !== response.data._id)],
        cart: [],
        selectedVoucher: null,
        voucherInput: '',
        voucherError: '',
        isSubmittingOrder: false,
        showCartModal: true
      }));
      this.fetchCustomerOrders();
      this.showNotification('success', 'Đặt món thành công', `Bếp đã nhận ${cart.length} món của ${tableName}.`);
    } catch (error) {
      this.setState({ isSubmittingOrder: false });
      this.showNotification('error', 'Chưa gửi được đơn', error.response?.data?.message || 'Vui lòng thử lại sau ít phút.');
    }
  }

  handleSendServiceRequest = async (serviceContent) => {
    if (this.state.isSubmittingServiceRequest) return;
    this.setState({ isSubmittingServiceRequest: true });
    try {
      const token = localStorage.getItem('token');
      await axios.post('/api/admin/service-requests', { tableNo: this.state.tableName, content: serviceContent }, {
        headers: token ? { 'x-access-token': token } : {}
      });
      this.setState({ showServiceModal: false, isSubmittingServiceRequest: false });
      this.showNotification('success', 'Đã gọi nhân viên', `Yêu cầu của ${this.state.tableName} đã được gửi đến lễ tân.`);
    } catch (error) {
      this.setState({ isSubmittingServiceRequest: false });
      this.showNotification('error', 'Chưa gửi được yêu cầu', error.response?.data?.message || 'Vui lòng thử lại sau ít phút.');
    }
  }

  handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('role');
    localStorage.removeItem('username');

    const loginUrl = new URL(
      process.env.REACT_APP_ADMIN_LOGIN_URL || '/admin/login',
      window.location.origin
    );
    loginUrl.searchParams.set('loggedOut', '1');
    window.location.assign(loginUrl.toString());
  }

  render() {
    const { 
      categories, 
      products, 
      selectedCategory, 
      searchTerm, 
      tableName, 
      accountName, 
      cart, 
      selectedProductForDetail, 
      showServiceModal, 
      showCartModal 
    } = this.state;

    const filteredProducts = products.filter(item => {
      const matchCat = selectedCategory === 'all' || item.category?._id === selectedCategory || item.category === selectedCategory;
      const matchSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase());
      return matchCat && matchSearch;
    });

    const totalCartCount = cart.reduce((sum, item) => sum + item.quantity, 0);

    return (
      <div className="customer-home-container">
        {/* HEADER MENU */}
        <div className="customer-header">
          <div className="header-content-wrapper">
            <div className="header-top-row">
              <div className="header-title">Menu đồ ăn - {tableName}</div>
              <div className="user-greeting-area">
                <span className="greeting-text">Chào: <b>{accountName}</b></span>
                <button className="btn-logout-inline" onClick={this.handleLogout}>
                  Đăng xuất
                </button>
              </div>
            </div>

            <div className="header-actions">
              <div className="search-box">
                <span>🔍</span>
                <input 
                  type="text" 
                  placeholder="Tìm kiếm món ăn..." 
                  value={searchTerm}
                  onChange={(e) => this.setState({ searchTerm: e.target.value })}
                />
              </div>
              <button className="action-btn" onClick={() => this.setState({ showServiceModal: true })}>
                Gọi phục vụ
              </button>
              <button className="action-btn" onClick={() => this.setState({ showCartModal: true })}>
                Món đã gọi ({totalCartCount})
              </button>
            </div>
          </div>
        </div>

        {/* NỘI DUNG CHÍNH (FLEXIBLE WRAPPER) */}
        <div className="customer-body">
          <div className="category-filter">
            <button 
              className={`cat-pill ${selectedCategory === 'all' ? 'active' : ''}`}
              onClick={() => this.setState({ selectedCategory: 'all' })}
            >
              Tất cả
            </button>
            {categories.map(cat => (
              <button 
                key={cat._id}
                className={`cat-pill ${selectedCategory === cat._id ? 'active' : ''}`}
                onClick={() => this.setState({ selectedCategory: cat._id })}
              >
                {cat.name}
              </button>
            ))}
          </div>

          <div className="section-info">
            <span>Danh sách món ({filteredProducts.length})</span>
          </div>

          {/* GRID TỰ ĐỘNG CHUYỂN CỘT TRÊN MÁY TÍNH & 1 CỘT TRÊN DI ĐỘNG */}
          <div className="product-grid">
            {filteredProducts.length > 0 ? filteredProducts.map(prod => (
              <div 
                key={prod._id} 
                className={`product-card ${prod.status === 'Active' ? '' : 'is-unavailable'}`}
                onClick={() => this.setState({ selectedProductForDetail: prod })}
              >
                <div className="product-info-left">
                  <img 
                    src={prod.image || 'https://via.placeholder.com/150'} 
                    alt={prod.name} 
                    className="product-img" 
                  />
                  <div className="product-details">
                    <h4>{prod.name}</h4>
                    {prod.status !== 'Active' && <span className="product-unavailable-label">Hết món</span>}
                    <p className="product-price">
                      {Number(prod.price || 0).toLocaleString('vi-VN')}đ
                    </p>
                  </div>
                </div>
                <button 
                  className="btn-add-item"
                  disabled={prod.status !== 'Active'}
                  aria-label={prod.status === 'Active' ? `Chọn ${prod.name}` : `${prod.name} đã hết`}
                  onClick={(e) => {
                    e.stopPropagation();
                    this.setState({ selectedProductForDetail: prod });
                  }}
                >
                  +
                </button>
              </div>
            )) : (
              <div className="empty-products-msg">
                Không tìm thấy món ăn phù hợp.
              </div>
            )}
          </div>
        </div>

        {/* POPUP MODALS */}
        {selectedProductForDetail && (
          <ProductDetailComponent 
            product={selectedProductForDetail}
            onClose={() => this.setState({ selectedProductForDetail: null })}
            onAddToCart={this.handleAddToCart}
          />
        )}

        {showServiceModal && (
          <ServiceModalComponent 
            onClose={() => this.setState({ showServiceModal: false })}
            onSubmitService={this.handleSendServiceRequest}
          />
        )}

        {showCartModal && (
          <CartModalComponent 
            cart={cart}
            isSubmittingOrder={this.state.isSubmittingOrder}
            onClose={() => this.setState({ showCartModal: false })}
            onSubmitOrder={this.handleSubmitOrder}
          />
        )}
      </div>
    );
  }
}

export default CustomerHomeComponent;
